//! Next.js-specific transforms and runtime resolution.

/// Build coordination directory shared by the App Router integration modules.
pub const APP_ADAPTER_DIR: &str = ".diffpack-next";

/// Whether a path belongs to source generated by either Next adapter.
pub fn is_generated_adapter_path(path: &std::path::Path) -> bool {
    path.components().any(|component| {
        matches!(
            component.as_os_str().to_str(),
            Some(APP_ADAPTER_DIR | next_pages::ADAPTER_DIR)
        )
    })
}

/// Standalone ESM compilation for Next-owned build-time modules, including JSX
/// in JavaScript extensions.
pub fn transform_to_standalone_esm(path: &std::path::Path, source: &str) -> Result<String, String> {
    diffpack_core::compiler::transform_to_standalone_esm_with_jsx(
        path,
        source,
        diffpack_core::parser::JsxExtensions::JsxInJavaScript,
    )
}

